/**
 * R prepares a reply from the open reader (keyboard-first). The key and the
 * "Prepare reply" palette entry use the same rule as the reader's buttons, the
 * source is always the displayed latest message, and the key is inert wherever
 * another surface or a text field owns the keyboard.
 */
import { afterEach, describe, expect, it } from 'vitest';
import { flushPromises, mount, type VueWrapper } from '@vue/test-utils';
import App from '../src/App.vue';
import { createBrowserFakeMailClient, fixtureRef, useGmailMode, waitFor, type BrowserFake } from './helpers';

let wrapper: VueWrapper | null = null;
afterEach(() => { wrapper?.unmount(); wrapper = null; document.body.innerHTML = ''; });

function press(init: KeyboardEventInit & { key: string }, target?: EventTarget): KeyboardEvent {
  const event = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, ...init });
  (target ?? document.activeElement ?? document.body).dispatchEvent(event);
  return event;
}

async function mountApp(fake: BrowserFake): Promise<VueWrapper> {
  wrapper = mount(App, { props: { client: fake, mode: 'browser-preview' }, attachTo: document.body });
  await flushPromises();
  return wrapper;
}

async function openReader(w: VueWrapper, id = 'conv-01'): Promise<void> {
  await w.get(`[data-test="conversation-row-${id}"]`).trigger('click');
  await flushPromises();
  expect(w.find('[data-test="reader"]').exists()).toBe(true);
}

async function drafts(fake: BrowserFake) {
  await flushPromises();
  return fake.listDrafts();
}

async function paletteIds(w: VueWrapper, query: string): Promise<string[]> {
  if (!w.find('[data-test="action-query"]').exists()) await w.get('[data-test="palette-trigger"]').trigger('click');
  await flushPromises();
  await w.get('[data-test="action-query"]').setValue(query);
  return w.findAll('[role="option"]').map((option) => option.attributes('id') ?? '');
}

/** Closes the palette so the next step starts from the reader or list. */
async function closePalette(w: VueWrapper): Promise<void> {
  if (!w.find('[data-test="action-query"]').exists()) return;
  press({ key: 'Escape' }, w.get('[data-test="action-query"]').element);
  await flushPromises();
  expect(w.find('[data-test="action-query"]').exists()).toBe(false);
}

describe('R: Prepare reply from the reader', () => {
  it('opens the docked composer for the displayed latest message, like the button, and focuses the body', async () => {
    const fake = createBrowserFakeMailClient();
    const w = await mountApp(fake);
    await openReader(w);
    // The button hint shows the key; the hidden name stays "Prepare reply".
    expect(w.get('[data-test="prepare-reply"]').attributes('title')).toContain('Prepare reply — R');
    expect(w.get('[data-test="prepare-reply"]').text()).toBe('Prepare reply');
    expect(w.get('[data-test="message-reply-conv-01-m3"]').attributes('title')).toBe('Prepare reply — R. Reply targets the latest message from Ada Fixture');
    expect(w.get('[data-test="message-reply-conv-01-m3"]').attributes('aria-label')).toBe('Prepare reply');

    // Focus an older message first: the source must still be the latest one.
    await w.get('[data-test="message-toggle-conv-01-m1"]').trigger('focusin');
    const event = press({ key: 'r' });
    expect(event.defaultPrevented).toBe(true);
    await waitFor(() => w.find('[data-test="reply-composer"]').exists());
    await flushPromises();
    const [draft] = await drafts(fake);
    expect(draft!.source).toEqual({ kind: 'reply', conversation: fixtureRef('conv-01'), sourceMessageId: 'conv-01-m3' });
    expect(w.find('[data-test="reader"]').exists()).toBe(true);
    // Focus ends in the body once the draft exists; Escape closes through the protected flush.
    await waitFor(() => document.activeElement === w.get('[data-test="draft-body"]').element);
    press({ key: 'Escape' });
    await waitFor(() => !w.find('[data-test="reply-composer"]').exists());
    expect(w.find('[data-test="reader"]').exists()).toBe(true);
    expect((await fake.listDrafts())).toHaveLength(1);
    await flushPromises();
    // Focus returns to the reader's active message instead of dropping to <body>.
    expect(document.activeElement).toBe(w.get('[data-test="message-toggle-conv-01-m1"]').element);
  });

  it.each([
    ['Shift', { shiftKey: true, key: 'R' }],
    ['Ctrl', { ctrlKey: true, key: 'r' }],
    ['Meta', { metaKey: true, key: 'r' }],
    ['Alt', { altKey: true, key: 'r' }],
    ['key repeat', { repeat: true, key: 'r' }],
    ['IME composition', { isComposing: true, key: 'r' }],
    ['IME keyCode 229', { keyCode: 229, key: 'r' }],
  ] as const)('is inert with %s', async (_name, init) => {
    const fake = createBrowserFakeMailClient();
    const w = await mountApp(fake);
    await openReader(w);
    press({ ...init });
    await flushPromises();
    expect(await drafts(fake)).toHaveLength(0);
    expect(w.find('[data-test="reply-composer"]').exists()).toBe(false);
  });

  it('is inert from a text field, a button other than a message toggle, and the list', async () => {
    const fake = createBrowserFakeMailClient();
    const w = await mountApp(fake);
    // List: no reader, no reply.
    press({ key: 'r' });
    await flushPromises();
    expect(await drafts(fake)).toHaveLength(0);
    await openReader(w);
    for (const tag of ['input', 'textarea']) {
      const field = document.createElement(tag);
      document.body.appendChild(field);
      field.focus();
      press({ key: 'r' }, field);
      field.remove();
    }
    press({ key: 'r' }, w.get('[data-test="files-links"]').element);
    await flushPromises();
    expect(await drafts(fake)).toHaveLength(0);
  });

  it('still works from the quoted-text toggle, which keeps focus after a click', async () => {
    const fake = createBrowserFakeMailClient();
    const w = await mountApp(fake);
    await openReader(w);
    // The fixture bodies carry no quote, so stand in for the toggle button the
    // reader renders inside a message: the key guard only looks at its class.
    const toggle = document.createElement('button');
    toggle.className = 'message-quote-toggle';
    w.get('[data-test="reader-messages"] .message').element.appendChild(toggle);
    toggle.focus();
    const event = press({ key: 'r' }, toggle);
    await flushPromises();
    expect(event.defaultPrevented).toBe(true);
    expect(await drafts(fake)).toHaveLength(1);
    toggle.remove();
  });

  it('does not open a second composer while one is open and keeps typing as text', async () => {
    const fake = createBrowserFakeMailClient();
    const w = await mountApp(fake);
    await openReader(w);
    press({ key: 'r' });
    await waitFor(() => w.find('[data-test="reply-composer"]').exists());
    await flushPromises();
    const body = w.get('[data-test="draft-body"]');
    await body.setValue('r');
    press({ key: 'r' }, body.element);
    press({ key: 'r' }, document.body);
    await flushPromises();
    expect(await fake.listDrafts()).toHaveLength(1);
    expect((body.element as HTMLTextAreaElement).value).toBe('r');
  });

  it.each([
    ['an incomplete conversation', (fake: BrowserFake) => fake.controls.markUnsupported('conv-01', 'plain text incomplete', false)],
    ['a retained recovery snapshot', (fake: BrowserFake) => fake.controls.markRetainedSnapshot('conv-01', '2025-02-03T04:05:06Z')],
  ])('is inert and absent from the palette for %s (the button is disabled by the same rule)', async (_name, block) => {
    const fake = createBrowserFakeMailClient();
    block(fake);
    const w = await mountApp(fake);
    await openReader(w);
    expect(w.find('[data-test="reply-blocked"]').exists()).toBe(true);
    expect(w.get('[data-test="prepare-reply"]').attributes('disabled')).toBeDefined();
    press({ key: 'r' });
    await flushPromises();
    expect(await drafts(fake)).toHaveLength(0);
    // The palette is open and working (other commands are found), reply just is not among them.
    expect(await paletteIds(w, 'mark done')).toContain('action-archive');
    expect(await paletteIds(w, 'prepare reply')).not.toContain('action-reply');
  });

  it('is inert in cached Trash', async () => {
    const fake = createBrowserFakeMailClient();
    useGmailMode(fake, { mutationAccess: 'enabled' });
    fake.controls.markTriage('conv-04', 'trash');
    const w = await mountApp(fake);
    await w.get('[data-test="palette-trigger"]').trigger('click');
    await w.get('[data-test="action-query"]').setValue('Go to cached Trash');
    press({ key: 'Enter' });
    await flushPromises();
    await w.get('button[data-id="conv-04"]').trigger('click');
    await flushPromises();
    expect(w.find('[data-test="reader"]').exists()).toBe(true);
    press({ key: 'r' });
    await flushPromises();
    expect(await drafts(fake)).toHaveLength(0);
    expect(await paletteIds(w, 'prepare reply')).not.toContain('action-reply');
  });

  it('lists "Prepare reply" with R in the palette only while the reader is open and reply is allowed', async () => {
    const fake = createBrowserFakeMailClient();
    const w = await mountApp(fake);
    // List view: absent, with the palette demonstrably open.
    expect(await paletteIds(w, 'reply')).not.toContain('action-reply');
    expect(await paletteIds(w, 'new message')).toContain('action-compose');
    await closePalette(w);
    await openReader(w);
    for (const query of ['prepare reply', 'respond', 'write back', 'r']) {
      expect(await paletteIds(w, query), query).toContain('action-reply');
    }
    await w.get('[data-test="action-query"]').setValue('prepare reply');
    const option = w.get('#action-reply');
    expect(option.text()).toContain('Prepare reply');
    expect(option.get('kbd').text()).toBe('R');
    // Running it from the palette uses the same path as the key.
    press({ key: 'Enter' }, w.get('[data-test="action-query"]').element);
    await waitFor(() => w.find('[data-test="reply-composer"]').exists());
    expect((await fake.listDrafts())[0]!.source).toEqual({ kind: 'reply', conversation: fixtureRef('conv-01'), sourceMessageId: 'conv-01-m3' });
  });
});
<script setup lang="ts">
/**
 * Inline reply composer docked at the bottom of the open reader (Superhuman
 * reply shot). The thread stays visible above it; this pane only edits the
 * local plain-text draft through the shared `useDrafts` state wired by App.
 * The editor body is the shared DraftEditorCore; this surface supplies the
 * docked shell, the compact "Reply draft to {sender}" heading and the
 * read-only quoted context.
 *
 * Frozen draft contract (vertical-slice-04): the quoted latest message is a
 * READ-ONLY context block — it is never inserted into `bodyText`, which stays
 * blank on prepare. No Send/send-later/AI/attachments/rich text/Bcc/reply-all:
 * the footer offers "Save and close" and "Discard…" only. All text is rendered
 * through interpolation; no v-html. The fixed reply source is exposed to tests
 * and tools as data attributes only; opaque provider IDs are never shown.
 */
import type { DraftContent, DraftRef, DraftSource, MailError } from '../lib/ipc/client';
import DraftEditorCore from './DraftEditorCore.vue';

const props = defineProps<{
  /** "Reply draft to {sender}" label: displayName ?? mailbox of the latest message. */
  recipientLabel: string;
  /** The latest message sender's mailbox: the default To. The recipient row shows the name only while To still equals it. */
  recipientMailbox?: string | null;
  /** Read-only quoted snippet of the latest message plain-text body. */
  quotedSnippet: string;
  activeRef: DraftRef | null;
  source: DraftSource | null;
  content: DraftContent;
  status: string;
  visible: boolean;
  creating: boolean;
  saving: boolean;
  conflict: boolean;
  error: MailError | null;
  createError: MailError | null;
  deleting: boolean;
  closing: boolean;
  transitioning: boolean;
  deletePending: boolean;
  confirmDiscard: boolean;
  discardBusy: boolean;
  confirmReload: boolean;
  copyPending: boolean;
  recoveryRequired: boolean;
  canCancelReplyPreparation: boolean;
  closeError: string | null;
}>();

const emit = defineEmits<{
  closeEditor: [];
  setField: [field: keyof DraftContent, value: string];
  retry: [];
  askDiscard: [];
  confirmDiscard: [];
  cancelDiscard: [];
  askReload: [];
  confirmReload: [];
  cancelReload: [];
  saveAsNew: [];
  cancelReplyPreparation: [];
}>();

function onSetField(field: keyof DraftContent, value: string): void {
  emit('setField', field, value);
}
</script>

<template>
  <section class="reply-composer" aria-label="Inline reply draft composer" data-test="reply-composer">
    <section v-if="props.visible" class="composer" aria-label="Plain-text draft editor" data-test="composer">
      <DraftEditorCore
        autofocus="body"
        variant="reply"
        :recipient-label="props.recipientLabel"
        :recipient-mailbox="props.recipientMailbox ?? null"
        :active-ref="props.activeRef"
        :source="props.source"
        :content="props.content"
        :status="props.status"
        :creating="props.creating"
        :saving="props.saving"
        :conflict="props.conflict"
        :error="props.error"
        :create-error="props.createError"
        :deleting="props.deleting"
        :closing="props.closing"
        :transitioning="props.transitioning"
        :delete-pending="props.deletePending"
        :confirm-discard="props.confirmDiscard"
        :discard-busy="props.discardBusy"
        :confirm-reload="props.confirmReload"
        :copy-pending="props.copyPending"
        :recovery-required="props.recoveryRequired"
        :can-cancel-reply-preparation="props.canCancelReplyPreparation"
        :close-error="props.closeError"
        @close-editor="emit('closeEditor')"
        @set-field="onSetField"
        @retry="emit('retry')"
        @ask-discard="emit('askDiscard')"
        @confirm-discard="emit('confirmDiscard')"
        @cancel-discard="emit('cancelDiscard')"
        @ask-reload="emit('askReload')"
        @confirm-reload="emit('confirmReload')"
        @cancel-reload="emit('cancelReload')"
        @save-as-new="emit('saveAsNew')"
        @cancel-reply-preparation="emit('cancelReplyPreparation')"
      >
        <template #header>
          <header class="composer-heading">
            <h2>Reply draft <span class="reply-to">to <span data-test="draft-recipient-label">{{ props.recipientLabel }}</span></span></h2>
          </header>
        </template>
        <template #context>
          <!-- The fixed reply source: attributes only, never visible text. -->
          <span
            v-if="props.source?.kind === 'reply'"
            hidden
            data-test="reply-source"
            :data-source-conversation="props.source.conversation.conversationId"
            :data-source-message="props.source.sourceMessageId"
          ></span>
          <!-- Read-only quoted context of the latest message. It is display-only:
               it is never part of bodyText and the saved reply body stays blank. -->
          <blockquote class="reply-quoted" data-test="reply-quoted-context" aria-label="Quoted latest message (read-only)">{{ props.quotedSnippet }}</blockquote>
        </template>
      </DraftEditorCore>
    </section>
  </section>
</template>

<style scoped>
/* Docked reply composer on the raised surface. Full 1px border, no accent
   side stripe. The shell scrolls only when the thread and composer genuinely
   do not fit; the body textarea, not the header stack, takes the space. */
.reply-composer {
  flex: 0 0 auto;
  min-height: 0;
  margin-top: 0.5rem;
  border: 1px solid var(--divider);
  border-radius: 6px;
  background: var(--surface-raised);
  color: var(--text-primary);
  font-size: var(--type-body);
  overflow-y: auto;
  max-height: 60%;
}

.composer {
  min-width: 0;
  padding: 0.4rem 0.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.reply-to {
  color: var(--text-secondary);
  font-weight: var(--weight-regular);
  overflow-wrap: anywhere;
}

/* Read-only quoted context: plain text only, never editable, never part of
   the draft body. UI face at the body size, clamped to three lines so it can
   never push the body down; the full snippet stays in the DOM text. */
.reply-quoted {
  margin: 0.3rem 0;
  padding: 0.1rem 0.5rem;
  border-left: 2px solid var(--rule);
  color: var(--text-secondary);
  font-family: var(--font-ui);
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  user-select: text;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  overflow: hidden;
}
</style>

